module best_friend_pairs (\n    input [1:0] n,\n    output [29:0] result\n);\n    reg [29:0] result_reg;\n    always @(*) begin\n        case(n)\n            2'b00: result_reg = 30'd10;\n            2'b01: result_reg = 30'd570;\n            2'b10: result_reg = 30'd46242;\n            default: result_reg = 30'd0;\n        endcase\n    end\n    assign result = result_reg;\nendmodule